/** Test jstype annotation on oneof fields with int64/uint64 types */
export interface OneofJsType {
    value: {
        oneofKind: "numberVal";
        numberVal: number;
    } | {
        oneofKind: "stringVal";
        stringVal: string;
    } | {
        oneofKind: "bigVal";
        bigVal: string;
    } | {
        oneofKind: undefined;
    };
}
